-- coaching: 공단 「국민체력100 동영상 정보」 오픈API(15108846) 영상을 영상 · 클립 표에 싣는다.
-- scripts/kspo_videos_to_sql.py --add-labels --ref a84d392 가 생성한다. 손으로 고치지 말고, AI 표가 바뀌면 새 V 파일로 다시 만든다.
-- 출처: family-fitness-ai 커밋 a84d392192a90210d8eb1be438b7a9a0725acede (입력 파일 마지막 변경 a84d392, 2026-09-30 10:06:53+09:00)
--   data/release/kspo_videos.csv 910줄(영상 한 편이 연령대 · 요인 · 단계마다 한 줄)
-- 이번 표: 영상 452편 = 클립 452개, 그중 운동 후보 452개.
--   연령대마다 받는 클립: YOUTH 101 · ADOLESCENT 351 · ADULT 197. 두 연령대에 드는 영상(「공통」) 197편은 클립 하나에 연령대 줄이 둘이다.
--   클립 행의 연령대 칸(첫 줄 값): YOUTH 101 · ADOLESCENT 154 · ADULT 197.
--   단계가 둘인 영상 106편 · 요인이 둘 이상인 영상 109편도 줄마다 후보가 된다.
-- 영상 한 편 = 클립 하나: clip_id = {video_id}-0, seq 1, 0초 ~ duration_sec. 표의 줄은 모두 video_exercise_labels 에 싣는다.
-- 영상은 media_url(mp4) · thumbnail_url 로 튼다. 표에 없는 제목 · 첫 장면 주소 · 준비물은 이미 실린 값을 그대로 둔다.
-- 이미 적재된 DB 에 다시 돌려도 된다: 있는 clip_id 는 고치고 켜고, 없으면 넣고, 이번 표에 없는 공단 클립은 끈다.
--   공단 클립의 연령대 · 요인 · 단계 줄은 모두 지우고 다시 넣는다. 영상은 labeled_by='AI' 행만 고치고, 없으면 넣는다.
--   유튜브 영상 · 클립은 건드리지 않는다. PostgreSQL 과 H2(MODE=PostgreSQL) 양쪽에서 그대로 실행되는 문법만 쓴다.
-- V164(AI 9d0ec87, 두 파일 형식) 다음 버전이다. AI 담당자가 develop 에 병합한 코드(PR #14) 위의 feature/AI-follow-ups 표로 싣는다.
--   영상 452편은 V164 와 같다 — 새로 켜거나 끄는 영상은 없다. 「공통」 197편은 이제 청소년에게도 간다(청소년 154 → 351편).
--   줄마다 요인 · 단계가 붙어 첫 줄 요인 · 단계가 바뀐 영상 107편, V164 의 요인 · 단계 쌍이 없어진 영상 70편이다.
--   (예: 팔굽혀펴기 00248 · 00351 등은 근력 · 근지구력 두 줄, 유소년 스트레칭 00410 ~ 00417 은 준비 · 정리 두 줄)
--   요인 줄이 하나도 없는 영상 22편(누워서 배가로근 수축 00234 등)은 요인 없이 싣는다 — AI 는 대상 요인이나 빈 요인으로 편성한다.
--   제목(exercise_name → name_on_video)이 바뀐 클립 75개, home_ok 39 · quiet 24 · needs_props 174편이 AI 표대로 바뀐다.
--   클립 source 칸은 AI 표 값(kspo)이다. 영상 인용 이름(citation_label)을 새 칸에 싣는다 — 대체 편성 인용이 AI 와 같은 이름을 쓴다.
alter table exercise_videos add column citation_label varchar(120);
create table video_exercise_labels (
    clip_id        varchar(48) not null,
    seq            smallint    not null,
    age_group      varchar(12) not null,
    fitness_factor varchar(20),
    phase          varchar(10) not null,
    constraint pk_video_exercise_labels primary key (clip_id, seq),
    constraint fk_video_exercise_labels_clip foreign key (clip_id) references video_exercises (clip_id),
    constraint ck_video_exercise_labels_phase check (phase in ('WARMUP', 'MAIN', 'COOLDOWN')),
    constraint ck_video_exercise_labels_factor check (fitness_factor is null or fitness_factor in
        ('CARDIO', 'STRENGTH', 'MUSCULAR_ENDURANCE', 'FLEXIBILITY', 'AGILITY', 'POWER', 'COORDINATION', 'BALANCE')),
    constraint ck_video_exercise_labels_age_group check (age_group in
        ('TODDLER', 'YOUTH', 'ADOLESCENT', 'ADULT', 'SENIOR'))
);
